"""容器使用的无符号变长整数（LEB128）。"""

from __future__ import annotations

from .errors import WFormatError

__all__ = ["encode_uvarint", "decode_uvarint", "MAX_SHIFT"]

MAX_SHIFT = 63


def encode_uvarint(value):
    """把非负整数编码为 LEB128 字节串。"""
    if not isinstance(value, int) or value < 0:
        raise ValueError("uvarint 只能编码非负整数")
    out = bytearray()
    while True:
        group = value & 0x7F
        value >>= 7
        if value:
            out.append(group | 0x80)
        else:
            out.append(group)
            return bytes(out)


def decode_uvarint(buf, pos=0):
    """从 ``buf[pos:]`` 解出一个 uvarint，返回 ``(value, next_pos)``。"""
    if pos >= len(buf):
        raise WFormatError("truncated", "uvarint 数据不足")
    return buf[pos] & 0x7F, pos + 1

"""容器尾部校验和。"""

from __future__ import annotations

import struct

__all__ = ["CRC_SIZE", "compute_crc", "pack_crc", "unpack_crc"]

CRC_SIZE = 4

_POLY = 0xEDB88320


def _build_table():
    table = []
    for index in range(256):
        crc = index
        for _ in range(8):
            crc = (crc >> 1) ^ (_POLY if crc & 1 else 0)
        table.append(crc)
    return table


_TABLE = _build_table()


def compute_crc(data):
    """返回 ``data`` 的 32 位校验和。"""
    crc = 0xFFFFFFFF
    for byte in data:
        crc = (crc >> 8) ^ _TABLE[(crc ^ byte) & 0xFF]
    return crc & 0xFFFFFFFF


def pack_crc(value):
    """把校验和打包成 4 字节。"""
    return struct.pack("<I", value & 0xFFFFFFFF)


def unpack_crc(buf, pos=0):
    """从 ``buf[pos:pos+4]`` 解出校验和。"""
    if pos + CRC_SIZE > len(buf):
        raise ValueError("校验和字段不完整")
    return struct.unpack_from("<I", buf, pos)[0]

