"""临时边界检查（跑完就删）。"""
import io
import struct
import zlib

from wfmt import (WFormatError, iter_records, pack, read_all, unpack, verify,
                  decode_uvarint, encode_uvarint)

SAMPLE = open('assets/sample.wfmt', 'rb').read()


class ShortReader(object):
    """每次最多只给 7 字节，模拟管道 / 非阻塞 IO 的短读。"""

    def __init__(self, data, cap=7):
        self._b = io.BytesIO(data)
        self.cap = cap
        self.sizes = []

    def read(self, size=-1):
        assert isinstance(size, int) and size > 0
        self.sizes.append(size)
        return self._b.read(min(size, self.cap))


sr = ShortReader(SAMPLE)
assert read_all(sr) == unpack(SAMPLE)
assert max(sr.sizes) <= 4096

# bytearray / memoryview 输入
assert verify(bytearray(SAMPLE)) is True
assert unpack(bytearray(SAMPLE)) == unpack(SAMPLE)
mv = memoryview(SAMPLE)
assert verify(mv) is True
assert unpack(mv) == unpack(SAMPLE)
assert pack(unpack(mv)) == SAMPLE

# 直接塞 bytes 也能工作
assert read_all(SAMPLE) == unpack(SAMPLE)
assert list(iter_records(SAMPLE)) == unpack(SAMPLE)

# 非阻塞 IO 返回 None
class NoneReader(ShortReader):
    def read(self, size=-1):
        assert isinstance(size, int) and size > 0
        data = self._b.read(min(size, self.cap))
        return data if data else None


assert read_all(NoneReader(SAMPLE)) == unpack(SAMPLE)

# 超大 length：不能 OOM，必须报 truncated
head = b'WFMT\x01' + struct.pack('<I', 1)
body = b'\x01' + encode_uvarint(2 ** 64 - 1)
blob = head + body + b'\x00' * ((-(len(head) + len(body))) % 4)
blob = blob + struct.pack('<I', zlib.crc32(blob))
try:
    unpack(blob)
except WFormatError as exc:
    print('huge length unpack ->', exc.kind)
else:
    raise AssertionError('expected error')
try:
    read_all(io.BytesIO(blob))
except WFormatError as exc:
    print('huge length stream ->', exc.kind)
else:
    raise AssertionError('expected error')

# 溢出 varint
try:
    decode_uvarint(b'\xff' * 12)
except WFormatError as exc:
    print('overflow varint ->', exc.kind)
try:
    decode_uvarint(b'\x80' * 3)
except WFormatError as exc:
    print('unterminated varint ->', exc.kind)
try:
    decode_uvarint(b'')
except WFormatError as exc:
    print('empty varint ->', exc.kind)
print('max uvarint', decode_uvarint(encode_uvarint(2 ** 64 - 1)))
try:
    encode_uvarint(2 ** 64)
except WFormatError as exc:
    print('encode too big ->', exc.kind, isinstance(exc, ValueError))

# 截断的所有前缀都必须是 WFormatError
for cut in range(0, len(SAMPLE) + 6):
    blob = SAMPLE[:cut]
    assert verify(blob) is False or blob == SAMPLE, cut
    try:
        unpack(blob)
    except WFormatError:
        pass
    else:
        if blob != SAMPLE:
            raise AssertionError('cut=%d 没有报错' % cut)
    try:
        read_all(io.BytesIO(blob))
    except WFormatError:
        pass
    except Exception as exc:
        raise AssertionError('cut=%d 泄漏 %r' % (cut, exc))
    else:
        if blob != SAMPLE:
            raise AssertionError('stream cut=%d 没有报错' % cut)

# 单字节篡改：全部报错，且不允许泄漏别的异常
import random
rnd = random.Random(1)
for _ in range(400):
    pos = rnd.randrange(len(SAMPLE))
    bad = bytearray(SAMPLE)
    bad[pos] ^= 1 << rnd.randrange(8)
    bad = bytes(bad)
    assert verify(bad) is False, pos
    try:
        unpack(bad)
    except WFormatError:
        pass
    else:
        raise AssertionError('tamper@%d 没有报错' % pos)
    try:
        read_all(io.BytesIO(bad))
    except WFormatError:
        pass
    else:
        raise AssertionError('stream tamper@%d 没有报错' % pos)

print('EDGE OK')

